import React from 'react';
import { Form, message, Button, Input } from 'antd';
import dynamic from 'next/dynamic';
import axios from 'axios';
import ReCAPTCHA from 'react-google-recaptcha'


const FeaturePanel = dynamic(import('../featurePanel'), {
  loading: () => <p />,
});

const passwordRegex =  /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*().,'"`~|\\=+\-_*^;:{}\[\]<>/?])[a-zA-Z\d!@#$%^&*().,'"`~|\\=+\-_*^;:{}\[\]<>/?]{12,}$/;

const ResetPassword = ({ token }) => {
  const recaptchaRef = React.useRef()
  const formRef = React.createRef();
  const [isLoading, setLoading] = React.useState(false)
  const resetPwd = async () => {
    const values = await formRef.current.validateFields();
    const captchaToken = await recaptchaRef.current.executeAsync()
    setLoading(true)
    const data = {
      password: values.resetPassword,
      captchaToken,
    }

    axios
      .post(
        `${process.env.AUTH_API_URL}/user/forgot-password/${ token }/confirm`,
        data,
        { withCredentials: true }
      )
      .then(() => {
        setLoading(false);
        message.success('Password Changed Successfully');
        window.location.href = `${process.env.REDIRECT_URL}/login`;
      })
      .catch((error) => {
        setLoading(false);
        const responseData = error.response?.data;

        if (responseData?.error?.password?.[0]) {
          message.error(responseData.error.password[0]);
          return;
        }

        if (error.response?.status === 400 && responseData?.error?.message) {
          message.error(responseData.error.message);
          return;
        }

        message.error('Something went wrong. Please try again later.');
      });
  };
  return (
    <div className="external-wrapper">
      <div className="external-wrapper-flex">
        <div className="external-form theme-dark">
          <div className="ext-onboard-header">
            <figure>
              <a href='https://uxcam.com'>
                <img src='/static/uxcam-new-white.svg' alt='UXCam' width='150px' />
              </a>
            </figure>
          </div>
          <div className="form-content">
            <Form
              ref={formRef}
              layout="vertical"
              className="form-global login-form"
              style={{ marginTop: '-50px' }}
            >
              <h3 style={{ marginBottom: '10px' }}>Reset your password!</h3>
              <Form.Item
                name="resetPassword"
                rules={[
                  {
                    required: true,
                    message: 'Password cannot be empty',
                  },
                  {
                    pattern: passwordRegex,
                    message:
                      'Password must be a minimum of 12 characters and include at least one lowercase letter, one uppercase letter, one digit, and one special character.',
                  },
                ]}
              >
                <div className="input-group">
                  <Input
                    type="password"
                    placeholder="Enter new password"
                    className="form-control"
                  />
                </div>
              </Form.Item>
              <ReCAPTCHA
              ref={recaptchaRef}
              size='invisible'
              sitekey={process.env.SITE_KEY}
                />
              <Button
                loading={isLoading}
                onClick={() => resetPwd()}
                htmlType="submit"
                className="login-form-button btn-gradient"
              >
                Reset password
              </Button>
            </Form>
          </div>
        </div>

        <div className="external-right-content">
          <FeaturePanel />
        </div>
      </div>
    </div>
  );
}
export default ResetPassword;
